(async()=>{const W=ms=>new Promise(r=>setTimeout(r,ms));const ids=APP.liveAll().map(r=>r.p.id);const s=APP.ASSIST.cur();if(s)ids.push(s.id);const out=[];for(const id of ids){APP.go('dossier',id);await W(1400);const bs=[...document.querySelectorAll('#main button.lp-dmv')].filter(b=>/^↪ گامِ/.test(b.textContent.trim()));out.push(id.slice(0,14)+': '+bs.length+' step-btns '+bs.slice(0,4).map(b=>b.textContent.trim().slice(0,60)).join(' | '));const b=bs.find(b=>/گامِ ۱ مالِ/.test(b.textContent));if(b){b.scrollIntoView({block:'center'});const lab=b.textContent.trim();b.click();await W(1600);const ask=document.querySelector('#main .lp-dmvask');const opts=[...document.querySelectorAll('#main .lp-dmvall,#main .lp-dmvone,#main .lp-dmvno')].map(x=>x.textContent.trim());window.__MVID=id;return 'IN '+id+' CLICKED «'+lab+'» || ASK: '+(ask?ask.textContent:'NONE')+' || OPTS: '+opts.join(' / ')+' || '+out.join(' ;; ');}}return 'NO STEP MOVE BTN ;; '+out.join(' ;; ')})()
